# shellcheck shell=bash
# Sourced by install.sh — generate Claude Code account functions

# ===========================================
# Phase 5: Generate Claude Code account functions (module: claude)
# ===========================================
# Every account is defined the same way in config.sh (CLAUDE_ACCOUNT_<N>_*).
# Secrets are referenced by variable name and read from .secrets at runtime,
# so the generated file never contains a token.

{ module_enabled claude && module_enabled zsh; } || return 0

echo ""
echo "Generating Claude Code accounts..."
echo ""

claude_outfile="$ALIASES_DIR/claude-accounts.sh"
cat > "$claude_outfile" <<'CLHDR'
# Auto-generated by install.sh — do not edit
# Claude Code account functions (from CLAUDE_ACCOUNT_<N>_* in config.sh)
# section: Claude accounts
CLHDR
outfile="$claude_outfile"

# Status line: add tools/claude-statusline.sh to each account's settings.json
# (CLAUDE_STATUSLINE=false opts out; a different statusLine is never replaced)
STATUSLINE_CMD="$DOTFILES_DIR/tools/claude-statusline.sh"
ensure_statusline() {
  local file current tmp
  file="$(target_path "$1")/settings.json"
  [ "${CLAUDE_STATUSLINE:-true}" = false ] && return 0
  if ! have jq; then
    info "$file" "statusLine skipped (jq not installed)"
    return 0
  fi
  if [ -f "$file" ]; then
    if ! current="$(jq -r '.statusLine.command // empty' "$file" 2>/dev/null)"; then
      fail "$file" "not valid JSON — statusLine not added"
      return 0
    fi
    if [ -n "$current" ] && [ "$current" != "$STATUSLINE_CMD" ]; then
      info "$file" "keeps its own statusLine"
      return 0
    fi
    [ "$current" = "$STATUSLINE_CMD" ] && { success "$file" ""; return 0; }
    tmp="$(mktemp)"
    jq --arg cmd "$STATUSLINE_CMD" '.statusLine = {type: "command", command: $cmd}' "$file" > "$tmp" &&
      cat "$tmp" > "$file"  # rewrite in place: keeps the file's permissions and symlinks
    rm -f "$tmp"
  else
    mkdir -p "$(dirname "$file")"
    jq -n --arg cmd "$STATUSLINE_CMD" '{statusLine: {type: "command", command: $cmd}}' > "$file"
  fi
  success "$file" "statusLine"
}

account_names=()
link_home_account=""
for i in $(seq 1 99); do
  name="$(claude_account "$i" NAME)"
  [ -z "$name" ] && break
  config_dir="$(claude_config_dir "$i")"
  acc_env="$(claude_account "$i" ENV)"
  acc_secret_env="$(claude_account "$i" SECRET_ENV)"
  pre_cmd="$(claude_account "$i" PRE_CMD)"

  env_keys=""; secret_keys=""
  for pair in $acc_env; do env_keys="${env_keys:+$env_keys }${pair%%=*}"; done
  for pair in $acc_secret_env; do secret_keys="${secret_keys:+$secret_keys }${pair%%=*} (from \$${pair#*=})"; done
  emit_doc "Launch Claude Code with the '${name}' account" "[claude-args]" \
    "arg:[claude-args]  Passed to claude unchanged (e.g. -c, --resume, -p \"prompt\")" \
    "detail:Config dir: ${config_dir}" \
    "$([ -n "$env_keys" ] && printf 'detail:Sets: %s' "$env_keys")" \
    "$([ -n "$secret_keys" ] && printf 'detail:Secrets: %s' "$secret_keys")" \
    "$([ -n "$pre_cmd" ] && printf 'detail:Runs first: %s (aborts if it fails)' "$pre_cmd")" \
    "example:claude-${name}" "example:claude-${name} -c" "example:claude-${name} -p \"explain this repo\""
  echo "# help" >> "$claude_outfile"
  {
    echo "claude-${name}() {"
    echo "  if [ \"\${1:-}\" = \"-h\" ] || [ \"\${1:-}\" = \"--help\" ]; then"
    echo "    cat <<'HELP'"
    echo "Usage: claude-${name} [claude-args]"
    echo ""
    echo "Launch Claude Code with the '${name}' account (config dir: ${config_dir})."
    echo "Arguments are passed to claude unchanged; 'claude --help' lists them."
    echo ""
    echo "Examples:"
    echo "  claude-${name}                         start a new session"
    echo "  claude-${name} -c                      continue the last session"
    echo "  claude-${name} -p \"explain this repo\"  one-off prompt, print and exit"
    echo "HELP"
    echo "    return 0"
    echo "  fi"
    # Fail early with a clear message instead of starting with an empty token
    for pair in $acc_secret_env; do
      secret_var="${pair#*=}"
      echo "  if [ -z \"\${${secret_var}:-}\" ]; then"
      echo "    echo \"claude-${name}: ${secret_var} is not set in .secrets\" >&2"
      echo "    return 1"
      echo "  fi"
    done
    [ -n "$pre_cmd" ] && echo "  ${pre_cmd} || return 1"
    echo "  printf '\\e]0;claude - ${name}\\a'"
    printf '  CLAUDE_CONFIG_DIR=%q \\\n' "$config_dir"
    for pair in $acc_env; do
      printf '  %s=%q \\\n' "${pair%%=*}" "${pair#*=}"
    done
    for pair in $acc_secret_env; do
      echo "  ${pair%%=*}=\"\${${pair#*=}}\" \\"
    done
    echo "  command claude \"\$@\""
    echo "}"
  } >> "$claude_outfile"

  # Config dir: either a symlink to ~/.claude (LINK_HOME) or a plain directory
  if [ "$(claude_account "$i" LINK_HOME)" = true ]; then
    if [ -n "$link_home_account" ]; then
      fail "CLAUDE_ACCOUNT_${i}_LINK_HOME" "only one account can link ~/.claude (already: $link_home_account)"
    elif [ "$TEST_MODE" = true ]; then
      info "claude-${name}" "would link $config_dir → ~/.claude"
      link_home_account="$name"
    else
      mkdir -p "$HOME/.claude"
      link_file "$HOME/.claude" "$config_dir"
      link_home_account="$name"
    fi
  else
    mkdir -p "$(target_path "$config_dir")"
  fi
  ensure_statusline "$config_dir"

  account_names+=("$name")
  success "Account: claude-${name}" ""
done

if [ ${#account_names[@]} -eq 0 ]; then
  info "No Claude accounts defined" "see CLAUDE_ACCOUNT_<N>_* in config.example.sh"
else
  default_account="${CLAUDE_DEFAULT_ACCOUNT:-${account_names[0]}}"
  if [[ " ${account_names[*]} " == *" $default_account "* ]]; then
    cat >> "$claude_outfile" <<CLDEFAULT

# Plain \`claude\` runs the default account (CLAUDE_DEFAULT_ACCOUNT)
# desc: Claude Code with the default account (claude-${default_account})
# usage: [claude-args]
# detail: Set CLAUDE_DEFAULT_ACCOUNT in config.sh to change the default.
# example: claude
claude() { claude-${default_account} "\$@"; }
CLDEFAULT
    success "Default account: claude-${default_account}" ""
  else
    fail "CLAUDE_DEFAULT_ACCOUNT=$default_account" "no account with that name"
  fi
fi
